import type { MultiPolygon } from "geojson";
import { Column, CreateDateColumn, Entity, PrimaryGeneratedColumn, UpdateDateColumn } from "typeorm";

/**
 * One wetland outline (mangrove, swamp, marsh, tidal flat) from Geofabrik's OpenStreetMap water
 * areas file (migration CreateWetlands). Rows only arrive through the map-layer loader.
 * The simplified copies `geom_z8` and `geom_z10` are generated by the table and not mapped here.
 */
@Entity("wetlands")
export class Wetland {
  @PrimaryGeneratedColumn("uuid")
  id!: string;

  @Column({ name: "country_code", type: "char", length: 3 })
  countryCode!: string;

  /** OpenStreetMap's id, as Geofabrik writes it. Unique. */
  @Column({ name: "osm_id", type: "varchar", length: 40 })
  osmId!: string;

  @Column({ type: "varchar", length: 200, nullable: true })
  name!: string | null;

  /** layer-rules.ts WETLAND_CLASSES. */
  @Column({ name: "wetland_class", type: "varchar", length: 12 })
  wetlandClass!: string;

  /** Geofabrik's `fclass` as delivered: wetland_mangrove, wetland_tidalflat... */
  @Column({ name: "osm_class", type: "varchar", length: 40 })
  osmClass!: string;

  @Column({ type: "geometry", spatialFeatureType: "MultiPolygon", srid: 4326, select: false })
  geom!: MultiPolygon;

  @Column({ name: "source_id", type: "uuid" })
  sourceId!: string;

  @CreateDateColumn({ name: "created_at", type: "timestamptz" })
  createdAt!: Date;

  @UpdateDateColumn({ name: "updated_at", type: "timestamptz" })
  updatedAt!: Date;
}
